extends Node
## Headless test of MatterLedger (task 66, M0). Prints one `LEDGER <case> ...` line per case and
## `AUTOTEST_LEDGER cases=N fails=F ok=<bool>`. «RED» cases are the known holes of the game (science-astra-open.md #1, #2, K3):
## the case PASSES when the ledger finds the hole with the right material and kilograms.

class Holder extends RefCounted:
	var kg := {}
	func report() -> Dictionary:
		return kg.duplicate()
	func move_to(other: Holder, mat: String, amount: float) -> void:
		kg[mat] = kg[mat] - amount
		other.kg[mat] = float(other.kg.get(mat, 0.0)) + amount

## The ground of the game as dig_layer.gd keeps it: one material label per node (K12, «top material»).
class OneLabelGround extends RefCounted:
	var units := PackedInt32Array()
	var label := PackedStringArray()
	func _init(n: int) -> void:
		units.resize(n)
		label.resize(n)
	func dump(count: int, mat: String) -> void:   # spreads the load evenly; the nodes that grow take the load's label
		var each := count / units.size()
		for i in units.size():
			units[i] += each
			label[i] = mat
	func report(unit_m3: float) -> Dictionary:
		var out := {}
		for i in units.size():
			out[label[i]] = float(out.get(label[i], 0.0)) + units[i] * unit_m3 * Matter.density(label[i])
		return out

## What the same ground would report if it kept a column per material (the F3 layered ground): the green control.
class ColumnGround extends RefCounted:
	var units := {}
	func dump(count: int, mat: String) -> void:
		units[mat] = int(units.get(mat, 0)) + count
	func report(unit_m3: float) -> Dictionary:
		var out := {}
		for m in units:
			out[m] = units[m] * unit_m3 * Matter.density(m)
		return out

class FlatGround extends Node:
	func dig_grid() -> Dictionary:
		return {origin = Vector2(-16, -16), spacing = 1.0, size = 32.0}
	func dig_sample(_i: int, _j: int) -> float:
		return 0.0
	func dig_open(x: float, z: float) -> bool:
		return absf(x) < 15.0 and absf(z) < 15.0
	func dig_obstacles(_rect: Rect2) -> Array:
		return []

var cases := 0
var fails := 0


