	t_transfer()
	t_sources_sinks()
	t_transform_declared()
	t_transform_undeclared()
	t_unnamed_loss_and_created_mass()
	t_snow_clay_mock()
	t_snow_clay_real_dig_layer()
	t_chips_stone_into_humus()
	t_bad_provider()
	t_deterministic()
	t_check_since_and_tick()
	print("AUTOTEST_LEDGER cases=%d fails=%d ok=%s" % [cases, fails, str(fails == 0)])
	get_tree().quit(1 if fails > 0 else 0)


func ok(case_name: String, cond: bool, detail := "") -> void:
	cases += 1
	if not cond:
		fails += 1
	print("LEDGER %s %s %s" % [case_name, "ok" if cond else "FAIL", detail])


func near(a: float, b: float, eps := 1.0e-6) -> bool:
	return absf(a - b) <= eps


func ledger() -> MatterLedger:
	var l := MatterLedger.new()
	l.tolerance_kg = 1.0e-6
	l.use_default_rules()
	for m in ["oak", "pine", "birch"]:
		l.set_family(m, "wood")
	for m in ["granite", "sandstone"]:
		l.set_family(m, "stone")
	l.set_family("glass", "glass")
	return l


# 1. a transfer between providers keeps the sum, per material and in total; registration order does not matter
func t_transfer() -> void:
	var bag := Holder.new()
	var pile := Holder.new()
	bag.kg = {oak = 12.0, granite = 5.0}
	pile.kg = {oak = 30.0, pine = 7.0}
	var l := ledger()
	l.register_provider("bag", bag.report)
	l.register_provider("pile", pile.report)
	var snap := l.snapshot()
	bag.move_to(pile, "oak", 3.5)
	pile.move_to(bag, "pine", 2.25)
	var r := l.check_since(snap)
	var c := l.census()
	var total := 0.0
	for m in c:
		total += c[m].total
	ok("transfer_keeps_sum", r.ok and near(total, 54.0) and near(c.oak.total, 42.0) and near(c.oak.where.pile, 33.5) and near(c.pine.where.bag, 2.25),
		"total=%.6f oak=%.6f pile.oak=%.6f" % [total, c.oak.total, c.oak.where.pile])
	var l2 := ledger()
	l2.register_provider("pile", pile.report)
	l2.register_provider("bag", bag.report)
	ok("registration_order_irrelevant", MatterLedger.census_text(l.census()) == MatterLedger.census_text(l2.census()))


